const builtInEmojiPath = "/emojis/";

/**
 * URL for a built-in emoji asset by its unified code point, as produced by
 * the emoji picker. Keep in sync with isBuiltInEmojiUrl.
 */
export const builtInEmojiUrl = (unified: string) =>
	`${builtInEmojiPath}${unified}.png`;

/**
 * Whether a source URL points at a built-in emoji asset generated by
 * builtInEmojiUrl.
 */
export const isBuiltInEmojiUrl = (src: string | undefined): boolean =>
	Boolean(src?.startsWith(builtInEmojiPath));
